$ cd /data/workspace; .venv/bin/python - <<'E'
import json
a=json.load(open('outputs/analytics.json'))
def walk(o,p='$',d=0,maxd=6):
    if isinstance(o,dict):
        for k,v in o.items():
            if isinstance(v,(dict)) and d<maxd: print('  '*d+k+'{}'); walk(v,p+'.'+k,d+1,maxd)
            elif isinstance(v,list): print('  '*d+k+f'[{len(v)}]')
            else: print('  '*d+f'{k}={str(v)[:70]}')
walk(a,maxd=5)
E
